CREATE TABLE owner (id TEXT PRIMARY KEY CHECK(id='owner'), username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE sessions (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES owner(id) ON DELETE CASCADE, token_hash TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL, expires_at TEXT NOT NULL);
CREATE INDEX session_expiry ON sessions(expires_at);
CREATE TABLE learner (owner_id TEXT PRIMARY KEY REFERENCES owner(id) ON DELETE CASCADE, preferences TEXT NOT NULL, preferences_revision INTEGER NOT NULL DEFAULT 0, resume TEXT, enrolled INTEGER NOT NULL DEFAULT 0);
CREATE TABLE content_registry (id TEXT PRIMARY KEY, kind TEXT NOT NULL, version INTEGER NOT NULL);
CREATE TABLE drafts (owner_id TEXT NOT NULL REFERENCES owner(id), exercise_id TEXT NOT NULL, content_version INTEGER NOT NULL, revision INTEGER NOT NULL, data TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY(owner_id,exercise_id));
CREATE TABLE draft_versions (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES owner(id), exercise_id TEXT NOT NULL, data TEXT NOT NULL, revision INTEGER NOT NULL, reason TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX draft_history ON draft_versions(owner_id,exercise_id,created_at DESC);
CREATE TABLE conflicts (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES owner(id), exercise_id TEXT NOT NULL, local TEXT NOT NULL, remote TEXT NOT NULL, created_at TEXT NOT NULL, resolved INTEGER NOT NULL DEFAULT 0);
CREATE TABLE receipts (owner_id TEXT NOT NULL REFERENCES owner(id), mutation_id TEXT NOT NULL, resource TEXT NOT NULL, response TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(owner_id,mutation_id));
CREATE TABLE attempts (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES owner(id), exercise_id TEXT NOT NULL, content_version INTEGER NOT NULL, mode TEXT NOT NULL, source TEXT NOT NULL, outcome TEXT NOT NULL, help_used INTEGER NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX attempts_activity ON attempts(owner_id,created_at DESC);
CREATE TABLE progress (owner_id TEXT NOT NULL REFERENCES owner(id), exercise_id TEXT NOT NULL, lesson_id TEXT NOT NULL, completed INTEGER NOT NULL DEFAULT 0, proficient INTEGER NOT NULL DEFAULT 0, help_used INTEGER NOT NULL DEFAULT 0, review_stage INTEGER NOT NULL DEFAULT 0, due_at TEXT NOT NULL, last_result TEXT NOT NULL, PRIMARY KEY(owner_id,exercise_id));
CREATE INDEX reviews_due ON progress(owner_id,due_at);
CREATE TABLE hints (owner_id TEXT NOT NULL REFERENCES owner(id), exercise_id TEXT NOT NULL, level INTEGER NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(owner_id,exercise_id,level));
CREATE TABLE jobs (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES owner(id), exercise_id TEXT NOT NULL, content_version INTEGER NOT NULL, mode TEXT NOT NULL, mutation_id TEXT NOT NULL, state TEXT NOT NULL, payload TEXT NOT NULL, result TEXT, worker_id TEXT, lease_token TEXT, lease_expires_at TEXT, cancelled INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(owner_id,mutation_id));
CREATE INDEX queued_jobs ON jobs(state,created_at);
CREATE TABLE workers (id TEXT PRIMARY KEY, available INTEGER NOT NULL, detail TEXT NOT NULL, heartbeat_at TEXT NOT NULL);
CREATE TABLE review_events (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES owner(id), exercise_id TEXT NOT NULL, answer TEXT NOT NULL, correct INTEGER NOT NULL, confidence TEXT NOT NULL, created_at TEXT NOT NULL);
